  1	import { ArrowRight, ArrowUpRight, Brain, Warning } from "@phosphor-icons/react";
  2	import { AnimatePresence, motion } from "framer-motion";
  3	import { useEffect, useState } from "react";
  4	import { useNavigate } from "react-router-dom";
  5	import {
  6	  Area,
  7	  AreaChart,
  8	  ReferenceLine,
  9	  ResponsiveContainer,
 10	  Tooltip as ReTooltip,
 11	  XAxis,
 12	} from "recharts";
 13	import CommandCenterZoneView from "../../components/ops/CommandCenterZoneView";
 14	import {
 15	  DATACENTER_FLOORS,
 16	  type FloorKey,
 17	  ZONE_INDICATOR_COLORS,
 18	} from "../../components/ops/commandCenterLayout";
 19	import { cascadeDelays, telemetryHistory } from "../../data/mock";
 20	import { useApp } from "../../store/appStore";
 21	import AnomalyPanel from "./AnomalyPanel";
 22	
 23	function LiveClock() {
 24	  const [t, setT] = useState(new Date());
 25	  useEffect(() => {
 26	    const id = setInterval(() => setT(new Date()), 1000);
 27	    return () => clearInterval(id);
 28	  }, []);
 29	  const h = t.getHours().toString().padStart(2, "0"),
 30	    m = t.getMinutes().toString().padStart(2, "0"),
 31	    s = t.getSeconds().toString().padStart(2, "0");
 32	  return (
 33	    <span className="font-mono text-[11px] text-zinc-500 tabular-nums tracking-[0.08em]">
 34	      {h}:{m}:{s}
 35	    </span>
 36	  );
 37	}
 38	
 39	function useCountUp(target: number, d = 900) {
 40	  const [count, setCount] = useState(0);
 41	  useEffect(() => {
 42	    const start = performance.now();
 43	    let f: number;
 44	    const tick = (now: number) => {
 45	      const p = Math.min((now - start) / d, 1);
 46	      setCount(Math.round((1 - (1 - p) ** 3) * target));
 47	      if (p < 1) f = requestAnimationFrame(tick);
 48	    };
 49	    f = requestAnimationFrame(tick);
 50	    return () => cancelAnimationFrame(f);
 51	  }, [target, d]);
 52	  return count;
 53	}
 54	
 55	const chartData = telemetryHistory.slice(18);
 56	
 57	export default function CommandCenter() {
 58	  const { assets, incidents, activeIncidentId, setActiveIncident } = useApp();
 59	  const navigate = useNavigate();
 60	  const [litNodes, setLitNodes] = useState<Set<string>>(new Set());
 61	  const [tick, setTick] = useState(0);
 62	  const [activeFloor, setActiveFloor] = useState<FloorKey>("Mechanical");
 63	
 64	  const incident = incidents.find((i) => i.id === activeIncidentId);
 65	  const criticalIncident = incidents.find((i) => i.severity === "critical");
 66	
 67	  useEffect(() => {
 68	    const t = setInterval(() => setTick((n) => n + 1), 1000);
 69	    return () => clearInterval(t);
 70	  }, []);
 71	
 72	  useEffect(() => {
 73	    if (!incident) {
 74	      setLitNodes(new Set());
 75	      return;
 76	    }
 77	    const timers: ReturnType<typeof setTimeout>[] = [];
 78	    incident.blastRadius.forEach((id) => {
 79	      timers.push(
 80	        setTimeout(
 81	          () => setLitNodes((prev) => new Set([...prev, id])),
 82	          (cascadeDelays[id] ?? 5) * 400
 83	        )
 84	      );
 85	    });
 86	    return () => {
 87	      timers.forEach(clearTimeout);
 88	      setLitNodes(new Set());
 89	    };
 90	  }, [incident]);
 91	
 92	  const online = assets.filter((a) => a.status !== "offline").length;
 93	  const activeInc = incidents.filter((i) => i.status !== "resolved").length;
 94	  const hitlPending = incidents.filter((i) => i.status === "hitl-pending").length;
 95	  const ttf = criticalIncident ? Math.max(0, criticalIncident.ttf - Math.floor(tick / 60)) : 0;
 96	
 97	  const onlineCount = useCountUp(online);
 98	  const incCount = useCountUp(activeInc);
 99	
100	  const kpis = [
101	    {
102	      label: "Online",
103	      value: `${onlineCount}/${assets.length}`,
104	      colorClass: "text-emerald-400",
105	      accentColor: "bg-emerald-500",
106	      glow: "rgba(52,211,153,0.08)",
107	    },
108	    {
109	      label: "Incidents",
110	      value: String(incCount),
111	      colorClass: activeInc > 0 ? "text-red-400" : "text-emerald-400",
112	      accentColor: activeInc > 0 ? "bg-red-500" : "bg-emerald-500",
113	      glow: activeInc > 0 ? "rgba(239,68,68,0.10)" : "rgba(52,211,153,0.06)",
114	    },
115	    {
116	      label: "Approvals",
117	      value: String(hitlPending),
118	      colorClass: hitlPending > 0 ? "text-amber-400" : "text-zinc-500",
119	      accentColor: hitlPending > 0 ? "bg-amber-500" : "bg-zinc-700",
120	      glow: hitlPending > 0 ? "rgba(245,158,11,0.08)" : "transparent",
121	    },
122	    {
123	      label: "PUE",
124	      value: "1.38",
125	      colorClass: "text-sky-400",
126	      accentColor: "bg-sky-500",
127	      glow: "rgba(56,189,248,0.06)",
128	    },
129	  ];
130	
131	  const floorZones = Object.entries(DATACENTER_FLOORS[activeFloor].zones);
132	
133	  return (
134	    <div className="flex h-full bg-[#050505] overflow-hidden">
135	      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
136	        {/* ── Header ────────────────────────────────────────────── */}
137	        <div className="px-5 pt-3.5 pb-3 border-b border-white/[0.05] flex-shrink-0">
138	          {/* Top row */}
139	          <div className="flex items-center justify-between mb-3">
140	            <div className="flex items-center gap-3 flex-wrap">
141	              {/* Live badge */}
142	              <div className="flex items-center gap-1.5">
143	                <span className="relative flex h-2 w-2">
144	                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-40" />
145	                  <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-400" />
146	                </span>
147	                <span className="text-[9px] font-bold tracking-[0.22em] uppercase text-emerald-500 font-mono">
148	                  Live
149	                </span>
150	              </div>
151	
152	              <span className="hidden sm:block w-px h-3.5 bg-white/[0.08]" />
153	
154	              {/* Facility identity */}
155	              <div className="hidden sm:flex items-center gap-2 text-[11px]">
156	                <span className="text-zinc-500 font-mono tracking-wider">DC-01</span>
157	                <span className="text-zinc-700">·</span>
158	                <span className="text-zinc-400">Facility Alpha</span>
159	              </div>
160	
161	              {/* Critical badge */}
162	              {criticalIncident && (
163	                <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/[0.08] border border-red-500/25">
164	                  <span className="w-1.5 h-1.5 rounded-full bg-red-400 status-pulse-red" />
165	                  <span className="text-[9px] text-red-400 font-bold uppercase tracking-[0.16em] font-mono">
166	                    1 Critical
167	                  </span>
168	                </div>
169	              )}
170	            </div>
171	
172	            <div className="flex items-center gap-3">
173	              <LiveClock />
174	              <button
175	                type="button"
176	                onClick={() => navigate("/ops/incidents")}
177	                className="hidden sm:flex items-center gap-1 text-[10px] text-zinc-600 hover:text-zinc-300 transition-colors duration-200 font-mono"
178	              >
179	                All incidents <ArrowUpRight size={9} weight="bold" />
180	              </button>
181	            </div>
182	          </div>
183	
184	          {/* KPI tiles */}
185	          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
186	            {kpis.map((k, i) => (
187	              <motion.div
188	                key={k.label}
189	                initial={{ opacity: 0, y: 8 }}
190	                animate={{ opacity: 1, y: 0 }}
191	                transition={{ delay: i * 0.06, duration: 0.4, ease: [0.32, 0.72, 0, 1] }}
192	                className="relative overflow-hidden bg-[#070707] rounded-xl border border-white/[0.06] px-3.5 py-3"
193	                style={{ boxShadow: `0 0 24px ${k.glow}, inset 0 1px 0 rgba(255,255,255,0.03)` }}
194	              >
195	                {/* Left accent bar */}
196	                <div
197	                  className={`absolute left-0 inset-y-3 w-[2.5px] rounded-r-full opacity-75 ${k.accentColor}`}
198	                />
199	                <p
200	                  className={`text-[24px] font-semibold tracking-[-0.04em] tabular-nums leading-none ${k.colorClass}`}
201	                >
202	                  {k.value}
203	                </p>
204	                <p className="text-[9px] text-zinc-600 mt-1.5 font-mono uppercase tracking-[0.12em] leading-none">
205	                  {k.label}
206	                </p>
207	              </motion.div>
208	            ))}
209	          </div>
210	        </div>
211	
212	        {/* ── Critical banner ───────────────────────────────────── */}
213	        {criticalIncident && (
214	          <motion.button
215	            initial={{ opacity: 0, y: -4 }}
216	            animate={{ opacity: 1, y: 0 }}
217	            onClick={() => setActiveIncident(criticalIncident.id)}
218	            className="mx-5 mt-2.5 flex-shrink-0 text-left"
219	          >
220	            <div className="relative overflow-hidden rounded-xl border border-red-500/25 hover:border-red-500/45 bg-[#0c0505] transition-all duration-300 group">
221	              {/* Scan line */}
222	              <div className="scan-line opacity-25" />
223	              {/* Left edge */}
224	              <div className="absolute left-0 top-0 bottom-0 w-[3px] bg-gradient-to-b from-red-500/90 via-red-500/50 to-transparent" />
225	              {/* Top glow line */}
226	              <div className="absolute top-0 left-6 right-0 h-px bg-gradient-to-r from-red-500/35 to-transparent" />
227	
228	              <div className="flex items-center gap-3 px-4 py-2.5 pl-5">
229	                <Warning size={12} weight="fill" className="text-red-400 flex-shrink-0" />
230	                <div className="flex-1 min-w-0">
231	                  <p className="text-[11px] font-semibold text-white leading-none">
232	                    CHILLER-A-03 — CHW supply rising · compressor at 97%
233	                  </p>
234	                  <p className="text-[9px] text-zinc-600 mt-0.5 font-mono leading-none">
235	                    <span className="text-red-400 font-bold tabular-nums">{ttf}m</span> to threshold
236	                    ·{" "}
237	                    <span className="text-amber-400">
238	                      {(criticalIncident.confidence * 100).toFixed(0)}% confidence
239	                    </span>{" "}
240	                    · 8 systems at risk
241	                  </p>
242	                </div>
243	                <div className="flex items-center gap-1 flex-shrink-0 opacity-60 group-hover:opacity-100 transition-opacity duration-200">
244	                  <span className="text-[9px] text-red-400 font-semibold font-mono uppercase tracking-widest">
245	                    View
246	                  </span>
247	                  <ArrowRight
248	                    size={9}
249	                    weight="bold"
250	                    className="text-red-400 group-hover:translate-x-0.5 transition-transform duration-200"
251	                  />
252	                </div>
253	              </div>
254	            </div>
255	          </motion.button>
256	        )}
257	
258	        {/* ── Floor selector tabs ───────────────────────────────── */}
259	        <div className="mx-5 mt-2.5 flex-shrink-0">
260	          <div className="flex items-center gap-1 p-1 bg-[#070707] rounded-xl border border-white/[0.05]">
261	            {(
262	              Object.entries(DATACENTER_FLOORS) as [
263	                FloorKey,
264	                (typeof DATACENTER_FLOORS)[FloorKey],
265	              ][]
266	            ).map(([key, cfg]) => {
267	              const isActive = activeFloor === key;
268	              const hasAlert = !!(key === "Mechanical" && criticalIncident);
269	              return (
270	                <button
271	                  key={key}
272	                  type="button"
273	                  onClick={() => setActiveFloor(key)}
274	                  className={`flex-1 flex items-center justify-center gap-2 px-3 py-1.5 rounded-[10px] text-[10px] font-medium transition-all duration-200 ${
275	                    isActive
276	                      ? "bg-white/[0.07] text-white border border-white/[0.09] shadow-[inset_0_1px_0_rgba(255,255,255,0.06)]"
277	                      : "text-zinc-600 hover:text-zinc-400 hover:bg-white/[0.03]"
278	                  }`}
279	                >
280	                  <span
281	                    className={`w-1.5 h-1.5 rounded-full flex-shrink-0 transition-opacity duration-200 ${
282	                      hasAlert ? "bg-red-400 status-pulse-red" : cfg.indicatorColor
283	                    } ${isActive ? "opacity-90" : "opacity-40"}`}
284	                  />
285	                  <span className="font-mono tracking-wider">{cfg.shortLabel}</span>
286	                  <span className="hidden md:block text-[9px] opacity-50">{cfg.subtitle}</span>
287	                </button>
288	              );
289	            })}
290	          </div>
291	        </div>
292	
293	        {/* ── Main canvas + right panel ─────────────────────────── */}
294	        <div
295	          className="flex-1 flex flex-col lg:grid min-h-0 mt-2.5 mx-5 mb-5 gap-3 overflow-hidden"
296	          style={{ gridTemplateColumns: "1fr 306px" }}
297	        >
298	          {/* Zone visualization */}
299	          <div
300	            className="relative rounded-2xl overflow-hidden border border-white/[0.05] bg-[#050708]"
301	            style={{ minHeight: "300px" }}
302	          >
303	            {/* Corner targeting brackets */}
304	            <span className="pointer-events-none absolute top-2.5 left-2.5 w-5 h-5 border-t border-l border-white/[0.15] rounded-tl z-10" />
305	            <span className="pointer-events-none absolute top-2.5 right-2.5 w-5 h-5 border-t border-r border-white/[0.15] rounded-tr z-10" />
306	            <span className="pointer-events-none absolute bottom-2.5 left-2.5 w-5 h-5 border-b border-l border-white/[0.15] rounded-bl z-10" />
307	            <span className="pointer-events-none absolute bottom-2.5 right-2.5 w-5 h-5 border-b border-r border-white/[0.15] rounded-br z-10" />
308	
309	            <CommandCenterZoneView
310	              assets={assets}
311	              incident={incident}
312	              litNodes={litNodes}
313	              activeFloor={activeFloor}
314	              onAssetClick={(id) => {
315	                const inc = incidents.find((i) => i.assetId === id || i.blastRadius.includes(id));
316	                if (inc) setActiveIncident(inc.id);
317	              }}
318	            />
319	
320	            {/* Floor label */}
321	            <div className="absolute top-4 left-5 pointer-events-none z-10">
322	              <span className="text-[8px] font-mono font-bold text-zinc-600 uppercase tracking-[0.22em]">
323	                {DATACENTER_FLOORS[activeFloor].label}
324	              </span>
325	            </div>
326	
327	            {/* Zone legend */}
328	            <div className="absolute bottom-4 left-5 flex flex-col gap-1.5 pointer-events-none z-10">
329	              {floorZones.map(([zoneName, zoneCfg]) => (
330	                <div key={zoneName} className="flex items-center gap-1.5">
331	                  <div
332	                    className={`w-1 h-1 rounded-full ${ZONE_INDICATOR_COLORS[zoneCfg.zone] ?? "bg-zinc-500"} opacity-50`}
333	                  />
334	                  <span className="text-[7px] font-mono text-zinc-700 tracking-wide">
335	                    {zoneName}
336	                  </span>
337	                </div>
338	              ))}
339	            </div>
340	          </div>
341	
342	          {/* ── Right panel ───────────────────────────────────── */}
343	          <div className="flex flex-col gap-2.5 min-h-0 overflow-hidden">
344	            {/* Telemetry chart */}
345	            <div
346	              className="rounded-2xl border border-white/[0.05] bg-[#060607] flex-shrink-0 overflow-hidden"
347	              style={{ height: 186 }}
348	            >
349	              <div className="px-4 pt-3 pb-0">
350	                <div className="flex items-center justify-between">
351	                  <div className="flex items-center gap-2">
352	                    <span className="w-1.5 h-1.5 rounded-full bg-red-400 status-pulse-red" />
353	                    <p className="text-[9px] text-zinc-500 font-mono uppercase tracking-[0.14em]">
354	                      CHILLER-A-03 · CHW Temp
355	                    </p>
356	                  </div>
357	                  <span className="text-[11px] text-red-400 font-mono font-bold tabular-nums">
358	                    {assets.find((a) => a.id === "chiller-a-03")?.telemetry[0].value.toFixed(1)}°C
359	                  </span>
360	                </div>
361	              </div>
362	              <ResponsiveContainer width="100%" height={152}>
363	                <AreaChart data={chartData} margin={{ top: 8, right: 0, left: 0, bottom: 0 }}>
364	                  <defs>
365	                    <linearGradient id="g1" x1="0" y1="0" x2="0" y2="1">
366	                      <stop offset="0%" stopColor="#ef4444" stopOpacity={0.25} />
367	                      <stop offset="100%" stopColor="#ef4444" stopOpacity={0} />
368	                    </linearGradient>
369	                  </defs>
370	                  <XAxis
371	                    dataKey="time"
372	                    tick={{ fontSize: 7, fill: "#3f3f46", fontFamily: "monospace" }}
373	                    interval={8}
374	                    axisLine={false}
375	                    tickLine={false}
376	                  />
377	                  <ReTooltip
378	                    contentStyle={{
379	                      background: "#0a0a0a",
380	                      border: "1px solid rgba(255,255,255,0.08)",
381	                      borderRadius: 8,
382	                      fontSize: 10,
383	                    }}
384	                  />
385	                  <ReferenceLine
386	                    x={chartData[18]?.time}
387	                    stroke="rgba(239,68,68,0.22)"
388	                    strokeDasharray="3 3"
389	                  />
390	                  <Area
391	                    type="monotone"
392	                    dataKey="chwTemp"
393	                    stroke="#ef4444"
394	                    strokeWidth={1.5}
395	                    fill="url(#g1)"
396	                    dot={false}
397	                  />
398	                </AreaChart>
399	              </ResponsiveContainer>
400	            </div>
401	
402	            {/* Active incidents + agent pipeline */}
403	            <div className="flex-1 rounded-2xl border border-white/[0.05] bg-[#060607] overflow-hidden flex flex-col">
404	              {/* Section header */}
405	              <div className="px-4 pt-3 pb-2 border-b border-white/[0.04] flex-shrink-0 flex items-center justify-between">
406	                <div className="flex items-center gap-2">
407	                  <div className="w-[2px] h-3.5 rounded-full bg-red-500/60" />
408	                  <p className="text-[9px] text-zinc-500 font-mono uppercase tracking-[0.15em]">
409	                    Active Incidents
410	                  </p>
411	                </div>
412	                <span className="text-[8px] font-mono text-zinc-700">{incidents.length} open</span>
413	              </div>
414	
415	              <div
416	                className="flex-1 overflow-y-auto p-3 space-y-2"
417	                style={{ scrollbarWidth: "none" }}
418	              >
419	                <AnimatePresence>
420	                  {incidents.map((inc, i) => {
421	                    const asset = assets.find((a) => a.id === inc.assetId);
422	                    const isCrit = inc.severity === "critical";
423	                    return (
424	                      <motion.button
425	                        key={inc.id}
426	                        initial={{ opacity: 0, x: 6 }}
427	                        animate={{ opacity: 1, x: 0 }}
428	                        transition={{ delay: i * 0.05, duration: 0.3, ease: [0.32, 0.72, 0, 1] }}
429	                        onClick={() => setActiveIncident(inc.id)}
430	                        className={`w-full text-left rounded-xl border overflow-hidden transition-all duration-300 ${
431	                          isCrit
432	                            ? "border-red-500/22 bg-red-500/[0.04] hover:border-red-500/45 hover:bg-red-500/[0.07]"
433	                            : "border-amber-500/18 bg-amber-500/[0.03] hover:border-amber-500/38 hover:bg-amber-500/[0.06]"
434	                        }`}
435	                      >
436	                        {/* Top accent gradient */}
437	                        <div
438	                          className={`h-px w-full ${
439	                            isCrit
440	                              ? "bg-gradient-to-r from-red-500/50 to-transparent"
441	                              : "bg-gradient-to-r from-amber-500/40 to-transparent"
442	                          }`}
443	                        />
444	                        <div className="px-3 py-2.5">
445	                          <div className="flex items-center justify-between gap-2">
446	                            <div className="flex items-center gap-2 min-w-0">
447	                              <Warning
448	                                size={10}
449	                                weight="fill"
450	                                className={isCrit ? "text-red-400" : "text-amber-400"}
451	                              />
452	                              <p className="text-[11px] font-semibold text-white truncate">
453	                                {asset?.name}
454	                              </p>
455	                            </div>
456	                            <p
457	                              className={`text-[13px] font-bold font-mono tabular-nums flex-shrink-0 ${
458	                                isCrit ? "text-red-400" : "text-amber-400"
