471	                </AnimatePresence>
472	
473	                {/* Agent pipeline mini-vis */}
474	                <div className="mt-1 rounded-xl border border-white/[0.05] bg-white/[0.015]">
475	                  <div className="px-3 py-2.5">
476	                    <div className="flex items-center gap-1.5 mb-3">
477	                      <Brain size={9} weight="light" className="text-zinc-600" />
478	                      <p className="text-[8px] text-zinc-600 font-mono uppercase tracking-[0.15em]">
479	                        Agent Pipeline
