481	                    </div>
482	                    <div className="flex items-center">
483	                      {[
484	                        { name: "Sentinel", short: "SEN", color: "#3b82f6", done: true },
485	                        { name: "Triton", short: "TRI", color: "#8b5cf6", done: true },
486	                        { name: "Hephaestus", short: "HEP", color: "#f97316", done: true },
487	                        { name: "Hermes", short: "HRM", color: "#10b981", done: true },
488	                        { name: "Mnemos", short: "MNM", color: "#f59e0b", done: false },
489	                      ].map((a, i) => (
490	                        <div key={a.name} className="flex items-center flex-1 min-w-0">
491	                          {i > 0 && (
492	                            <div
493	                              className="flex-1 h-px"
494	                              style={{
495	                                background: a.done
496	                                  ? `linear-gradient(90deg, ${a.color}60, ${a.color}30)`
