501	                          <div className="flex flex-col items-center gap-1 flex-shrink-0">
502	                            <div
503	                              className="w-2 h-2 rounded-full"
504	                              style={{
505	                                backgroundColor: a.done ? a.color : "transparent",
506	                                border: `1.5px solid ${a.done ? a.color : "rgba(255,255,255,0.12)"}`,
507	                                boxShadow: a.done ? `0 0 7px ${a.color}55` : "none",
