1	import {
2	  ArrowRight,
3	  Brain,
4	  CaretRight,
5	  ChartLineUp,
6	  CheckCircle,
7	  Circle,
8	  ClockCountdown,
9	  MagnifyingGlass,
10	  Robot,
11	  Spinner,
12	  Warning,
13	} from "@phosphor-icons/react";
14	import { AnimatePresence, motion } from "framer-motion";
15	import { useRef, useState } from "react";
16	import { assets, incidents, jobs, technicians } from "../../data/mock";
17	
18	// ── Types ─────────────────────────────────────────────────────────────────
19	
20	type PipelineStep = "sentinel" | "triton" | "hermes";
21	type ResultType = "asset-list" | "cascade" | "technician" | "forecast" | "generic";
22	
23	interface PipelineState {
24	  step: PipelineStep | "done" | "idle";
25	  durations: Partial<Record<PipelineStep, number>>;
26	}
27	
28	interface QueryResult {
29	  type: ResultType;
30	  summary: string;
31	  data: unknown;
32	}
33	
34	// ── Example queries ────────────────────────────────────────────────────────
35	
36	const EXAMPLE_QUERIES = [
37	  "Which assets are in a critical or warning state?",
38	  "Show me the blast radius of the active incident",
39	  "Who is the nearest available technician?",
40	  "What is the thermal forecast for CHILLER-A-03?",
41	  "List all cooling assets on Hall B",
42	];
43	
44	// ── Pipeline config ────────────────────────────────────────────────────────
45	
46	const PIPELINE_AGENTS = [
47	  {
48	    id: "sentinel" as PipelineStep,
49	    name: "Sentinel",
50	    short: "SEN",
51	    color: "#3b82f6",
52	    label: "Anomaly Detection",
53	  },
54	  {
55	    id: "triton" as PipelineStep,
56	    name: "Triton",
57	    short: "TRI",
58	    color: "#8b5cf6",
59	    label: "Quantile Forecast",
60	  },
61	  {
62	    id: "hermes" as PipelineStep,
63	    name: "Hermes",
64	    short: "HRM",
65	    color: "#10b981",
66	    label: "Query Resolution",
67	  },
68	];
69	
70	// ── Query resolver ─────────────────────────────────────────────────────────
71	
72	function resolveQuery(q: string): QueryResult {
73	  const lower = q.toLowerCase();
74	
75	  // blast radius / cascade
76	  if (lower.includes("blast") || lower.includes("cascade") || lower.includes("incident")) {
77	    const inc = incidents[0];
78	    const affected = inc.blastRadius.map((id) => assets.find((a) => a.id === id)).filter(Boolean);
79	    return {
80	      type: "cascade",
81	      summary: `Active incident on ${assets.find((a) => a.id === inc.assetId)?.name}. ${inc.blastRadius.length} assets in blast radius.`,
82	      data: { incident: inc, affected },
83	    };
84	  }
85	
86	  // technician
87	  if (
88	    lower.includes("technician") ||
89	    lower.includes("dispatch") ||
90	    lower.includes("nearest") ||
91	    lower.includes("available")
92	  ) {
93	    const avail = technicians.filter((t) => t.status === "available" || t.status === "transit");
94	    return {
95	      type: "technician",
96	      summary: `${avail.length} technician${avail.length !== 1 ? "s" : ""} available or in transit.`,
97	      data: { technicians: avail, job: jobs[0] },
98	    };
99	  }
100	
101	  // forecast
102	  if (
103	    lower.includes("forecast") ||
104	    lower.includes("thermal") ||
105	    lower.includes("temp") ||
106	    lower.includes("predict")
107	  ) {
108	    return {
109	      type: "forecast",
110	      summary: "Quantile forecast from Triton LightGBM model for CHILLER-A-03.",
111	      data: { asset: assets.find((a) => a.id === "chiller-a-03"), ttf: 23, confidence: 0.94 },
112	    };
113	  }
114	
115	  // asset list (critical/warning or type-based)
116	  const statusFilter = lower.includes("critical")
117	    ? "critical"
118	    : lower.includes("warning")
119	      ? "warning"
120	      : lower.includes("offline")
121	        ? "offline"
122	        : lower.includes("normal")
123	          ? "normal"
124	          : null;
125	
126	  const typeFilter = lower.includes("cooling")
127	    ? "Cooling"
128	    : lower.includes("power")
129	      ? "Power"
130	      : lower.includes("compute")
131	        ? "Compute"
132	        : lower.includes("network")
133	          ? "Network"
134	          : null;
135	
136	  const floorFilter = lower.includes("hall b")
137	    ? "Hall B"
138	    : lower.includes("hall a")
139	      ? "Hall A"
140	      : lower.includes("mechanical")
141	        ? "Mechanical"
142	        : null;
143	
144	  if (statusFilter || typeFilter || floorFilter) {
145	    const result = assets.filter((a) => {
146	      if (statusFilter && a.status !== statusFilter) return false;
147	      if (typeFilter && a.type !== typeFilter) return false;
148	      if (floorFilter && a.floor !== floorFilter) return false;
149	      return true;
150	    });
151	    return {
152	      type: "asset-list",
153	      summary: `Found ${result.length} asset${result.length !== 1 ? "s" : ""} matching your query.`,
154	      data: { assets: result.slice(0, 12) },
155	    };
156	  }
157	
158	  // generic fallback
159	  return {
160	    type: "generic",
161	    summary: `Queried ${assets.length} assets, ${incidents.length} active incident${incidents.length !== 1 ? "s" : ""}, ${technicians.length} technicians across 3 floors.`,
162	    data: {
163	      stats: {
164	        assets: assets.length,
165	        critical: assets.filter((a) => a.status === "critical").length,
166	        warning: assets.filter((a) => a.status === "warning").length,
167	        incidents: incidents.length,
168	      },
169	    },
170	  };
171	}
172	
173	// ── Status badge ──────────────────────────────────────────────────────────
174	
175	const STATUS_DOT: Record<string, string> = {
176	  normal: "bg-emerald-400",
177	  warning: "bg-amber-400",
178	  critical: "bg-red-400",
179	  offline: "bg-zinc-600",
180	};
181	const STATUS_TEXT: Record<string, string> = {
182	  normal: "text-emerald-400",
183	  warning: "text-amber-400",
184	  critical: "text-red-400",
185	  offline: "text-zinc-500",
186	};
187	
188	// ── Result renderers ──────────────────────────────────────────────────────
189	
190	function ResultAssetList({ data }: { data: { assets: typeof assets } }) {
191	  return (
192	    <div className="space-y-1.5">
193	      {data.assets.map((a, i) => (
194	        <motion.div
195	          key={a.id}
196	          initial={{ opacity: 0, x: 8 }}
197	          animate={{ opacity: 1, x: 0 }}
198	          transition={{ delay: i * 0.04, duration: 0.25, ease: [0.32, 0.72, 0, 1] }}
199	          className="flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2"
200	        >
201	          <span className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${STATUS_DOT[a.status]}`} />
202	          <span className="text-[11px] font-mono font-semibold text-white w-[110px] flex-shrink-0">
203	            {a.name}
204	          </span>
205	          <span className="text-[9px] font-mono text-zinc-600 flex-1 truncate">
206	            {a.floor} · {a.zone}
207	          </span>
208	          <span className={`text-[9px] font-mono ${STATUS_TEXT[a.status]}`}>{a.status}</span>
209	        </motion.div>
210	      ))}
211	    </div>
212	  );
213	}
214	
215	function ResultCascade({
216	  data,
217	}: {
218	  data: { incident: (typeof incidents)[0]; affected: ((typeof assets)[0] | undefined)[] };
219	}) {
220	  return (
221	    <div className="space-y-2">
222	      {/* incident card */}
223	      <div className="relative overflow-hidden rounded-xl border border-red-500/25 bg-red-500/[0.04] px-3.5 py-3">
224	        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-red-500/40 to-transparent" />
225	        <div className="absolute left-0 top-0 bottom-0 w-[2.5px] bg-gradient-to-b from-red-500/80 to-transparent" />
226	        <div className="flex items-center gap-2 mb-1.5">
227	          <Warning size={10} weight="fill" className="text-red-400" />
228	          <span className="text-[10px] font-semibold text-red-300">
229	            {data.incident.severity.toUpperCase()} · {data.incident.confidence * 100}% confidence
230	          </span>
231	          <span className="ml-auto text-[11px] font-mono font-bold text-red-400 tabular-nums">
232	            {data.incident.ttf}m TTF
233	          </span>
234	        </div>
235	        <p className="text-[8px] text-zinc-500 leading-relaxed line-clamp-2">
236	          {data.incident.prediction}
237	        </p>
238	      </div>
239	      {/* blast radius */}
240	      <div>
241	        <p className="text-[8px] font-mono text-zinc-700 uppercase tracking-[0.15em] mb-1.5">
242	          Blast Radius
243	        </p>
244	        <div className="flex flex-wrap gap-1.5">
245	          {(data.affected.filter(Boolean) as NonNullable<(typeof data.affected)[0]>[]).map(
246	            (a, i) => (
247	              <motion.span
248	                key={a.id}
249	                initial={{ opacity: 0, scale: 0.9 }}
250	                animate={{ opacity: 1, scale: 1 }}
251	                transition={{ delay: i * 0.05, duration: 0.2 }}
252	                className="flex items-center gap-1 text-[8px] font-mono px-2 py-1 rounded-lg border border-amber-500/20 bg-amber-500/[0.05] text-amber-400"
253	              >
254	                <span className="w-1 h-1 rounded-full bg-amber-400" />
255	                {a.name}
256	              </motion.span>
257	            )
258	          )}
259	        </div>
260	      </div>
261	    </div>
262	  );
263	}
264	
265	function ResultTechnician({
266	  data,
267	}: {
268	  data: { technicians: typeof technicians; job: (typeof jobs)[0] };
269	}) {
270	  const statusColor = {
271	    available: "text-emerald-400",
272	    transit: "text-sky-400",
273	    "on-site": "text-amber-400",
274	  };
275	  const statusDot = {
276	    available: "bg-emerald-400",
277	    transit: "bg-sky-400",
278	    "on-site": "bg-amber-400",
279	  };
280	
281	  return (
282	    <div className="space-y-2">
283	      {data.technicians.map((t, i) => (
284	        <motion.div
285	          key={t.id}
286	          initial={{ opacity: 0, x: 8 }}
287	          animate={{ opacity: 1, x: 0 }}
288	          transition={{ delay: i * 0.07, duration: 0.25, ease: [0.32, 0.72, 0, 1] }}
289	          className="flex items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 py-2.5"
290	        >
291	          <div className="w-7 h-7 rounded-full bg-white/[0.06] border border-white/[0.10] flex items-center justify-center flex-shrink-0">
292	            <span className="text-[9px] font-semibold text-zinc-300">{t.avatar}</span>
293	          </div>
294	          <div className="flex-1 min-w-0">
295	            <p className="text-[11px] font-semibold text-white">{t.name}</p>
296	            <p className="text-[8px] text-zinc-600 font-mono mt-0.5">
297	              {t.certifications.slice(0, 2).join(" · ")}
298	            </p>
299	          </div>
300	          <div className="text-right flex-shrink-0">
301	            <div className={`flex items-center gap-1 justify-end ${statusColor[t.status]}`}>
302	              <span className={`w-1.5 h-1.5 rounded-full ${statusDot[t.status]}`} />
303	              <span className="text-[9px] font-mono">{t.status}</span>
304	            </div>
305	            {t.eta && <p className="text-[8px] font-mono text-zinc-700 mt-0.5">{t.eta}</p>}
306	          </div>
307	        </motion.div>
308	      ))}
309	      {data.job && (
310	        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 py-2.5">
311	          <div className="flex items-center gap-2">
312	            <ClockCountdown size={9} className="text-zinc-600" />
313	            <span className="text-[9px] font-mono text-zinc-500 uppercase tracking-widest">
314	              Active Job
315	            </span>
316	          </div>
317	          <p className="text-[10px] text-zinc-300 font-semibold mt-1">{data.job.title}</p>
318	          <p className="text-[8px] text-zinc-700 font-mono mt-0.5">
319	            ETA: {data.job.eta} · {data.job.status}
320	          </p>
321	        </div>
322	      )}
323	    </div>
324	  );
325	}
326	
327	function ResultForecast({
328	  data,
329	}: {
330	  data: { asset: (typeof assets)[0] | undefined; ttf: number; confidence: number };
331	}) {
332	  if (!data.asset) return null;
333	  const t = data.asset.telemetry[0];
334	  return (
335	    <div className="space-y-2">
336	      <div className="relative overflow-hidden rounded-xl border border-red-500/20 bg-[#0c0505] px-3.5 py-3">
337	        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-red-500/30 to-transparent" />
338	        <div className="flex items-center gap-2 mb-2">
339	          <ChartLineUp size={10} weight="fill" className="text-red-400" />
340	          <span className="text-[10px] font-semibold text-white">{data.asset.name}</span>
341	          <span className="ml-auto text-[9px] font-mono text-red-400">
342	            {(data.confidence * 100).toFixed(0)}% conf
343	          </span>
344	        </div>
345	        {t && (
346	          <div className="flex items-end gap-1.5 mb-2">
347	            <span className="text-[28px] font-semibold text-red-400 leading-none tabular-nums font-mono">
348	              {t.value.toFixed(1)}
349	            </span>
350	            <span className="text-[12px] text-zinc-500 mb-0.5">{t.unit}</span>
351	            <span className="text-[9px] text-red-400 ml-1 mb-0.5">↑</span>
352	          </div>
353	        )}
354	        <div className="grid grid-cols-3 gap-2">
355	          {[
356	            { label: "q50 +18m", value: "13.2°C", color: "text-red-400" },
357	            { label: "TTF", value: `${data.ttf}m`, color: "text-amber-400" },
358	            { label: "Threshold", value: "12.0°C", color: "text-zinc-500" },
359	          ].map((s) => (
360	            <div
361	              key={s.label}
362	              className="rounded-lg bg-white/[0.03] border border-white/[0.05] px-2 py-1.5"
363	            >
364	              <p className={`text-[11px] font-mono font-semibold tabular-nums ${s.color}`}>
365	                {s.value}
366	              </p>
367	              <p className="text-[7px] font-mono text-zinc-700 uppercase tracking-wider mt-0.5">
368	                {s.label}
369	              </p>
370	            </div>
371	          ))}
372	        </div>
373	      </div>
374	      <div>
375	        <p className="text-[8px] font-mono text-zinc-700 uppercase tracking-[0.15em] mb-1.5">
376	          Affected Assets
377	        </p>
378	        <div className="flex flex-wrap gap-1.5">
379	          {["PUMP-CHW-03", "PUMP-CHW-04", "CRAH-B-01", "CRAH-B-02", "POD-05"].map((n, i) => (
380	            <motion.span
381	              key={n}
382	              initial={{ opacity: 0 }}
383	              animate={{ opacity: 1 }}
384	              transition={{ delay: 0.1 + i * 0.05 }}
385	              className="text-[8px] font-mono px-2 py-1 rounded-lg border border-amber-500/20 bg-amber-500/[0.05] text-amber-400"
386	            >
387	              {n}
388	            </motion.span>
389	          ))}
390	        </div>
391	      </div>
392	    </div>
393	  );
394	}
395	
396	function ResultGeneric({
397	  data,
398	}: {
399	  data: { stats: { assets: number; critical: number; warning: number; incidents: number } };
400	}) {
401	  const { stats } = data;
402	  return (
403	    <div className="grid grid-cols-2 gap-2">
404	      {[
405	        { label: "Total Assets", value: stats.assets, color: "text-zinc-300" },
406	        { label: "Incidents", value: stats.incidents, color: "text-red-400" },
407	        { label: "Critical", value: stats.critical, color: "text-red-400" },
408	        { label: "Warning", value: stats.warning, color: "text-amber-400" },
409	      ].map((s, i) => (
410	        <motion.div
411	          key={s.label}
412	          initial={{ opacity: 0, y: 6 }}
413	          animate={{ opacity: 1, y: 0 }}
414	          transition={{ delay: i * 0.06, duration: 0.25 }}
415	          className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5"
416	        >
417	          <p className={`text-[22px] font-semibold tabular-nums leading-none ${s.color}`}>
418	            {s.value}
419	          </p>
420	          <p className="text-[8px] font-mono text-zinc-600 uppercase tracking-[0.12em] mt-1">
421	            {s.label}
422	          </p>
423	        </motion.div>
424	      ))}
425	    </div>
426	  );
427	}
428	
429	// ── Pipeline indicator ────────────────────────────────────────────────────
430	
431	const STEP_ORDER: PipelineStep[] = ["sentinel", "triton", "hermes"];
432	
433	function PipelineBar({ state }: { state: PipelineState }) {
434	  const currentIdx =
435	    state.step === "idle"
436	      ? -1
437	      : state.step === "done"
438	        ? 3
439	        : STEP_ORDER.indexOf(state.step as PipelineStep);
440	
441	  return (
442	    <div className="flex items-center gap-0">
443	      {PIPELINE_AGENTS.map((agent, i) => {
444	        const done = currentIdx > i || state.step === "done";
445	        const active = currentIdx === i;
446	        return (
447	          <div key={agent.id} className="flex items-center flex-1 min-w-0">
448	            {i > 0 && (
449	              <div
450	                className="flex-1 h-px transition-all duration-500"
451	                style={{
452	                  background: done
453	                    ? `linear-gradient(90deg, ${PIPELINE_AGENTS[i - 1].color}60, ${agent.color}40)`
454	                    : "rgba(255,255,255,0.05)",
455	                }}
456	              />
457	            )}
458	            <div className="flex flex-col items-center gap-1.5 flex-shrink-0">
459	              <div
460	                className="w-6 h-6 rounded-full flex items-center justify-center transition-all duration-400"
461	                style={{
462	                  backgroundColor: done
463	                    ? `${agent.color}22`
464	                    : active
465	                      ? `${agent.color}15`
466	                      : "rgba(255,255,255,0.03)",
467	                  border: `1.5px solid ${done ? agent.color : active ? `${agent.color}60` : "rgba(255,255,255,0.08)"}`,
468	                  boxShadow: done || active ? `0 0 12px ${agent.color}44` : "none",
469	                }}
470	              >
471	                {done ? (
472	                  <CheckCircle size={11} weight="fill" style={{ color: agent.color }} />
473	                ) : active ? (
474	                  <Spinner size={10} className="animate-spin" style={{ color: agent.color }} />
475	                ) : (
476	                  <Circle size={8} style={{ color: "rgba(255,255,255,0.15)" }} />
477	                )}
478	              </div>
479	              <div className="text-center">
480	                <p
481	                  className="text-[8px] font-mono font-semibold"
482	                  style={{ color: done || active ? agent.color : "rgba(255,255,255,0.2)" }}
483	                >
484	                  {agent.short}
485	                </p>
486	                <p className="text-[7px] font-mono text-zinc-700 leading-none mt-0.5 hidden sm:block">
487	                  {agent.label}
488	                </p>
489	              </div>
490	            </div>
491	          </div>
492	        );
493	      })}
494	    </div>
495	  );
496	}
497	
498	// ── Main page ─────────────────────────────────────────────────────────────
499	
500	export default function NLQuery() {
501	  const [query, setQuery] = useState("");
502	  const [pipeline, setPipeline] = useState<PipelineState>({ step: "idle", durations: {} });
503	  const [result, setResult] = useState<QueryResult | null>(null);
504	  const [history, setHistory] = useState<{ query: string; result: QueryResult }[]>([]);
505	  const inputRef = useRef<HTMLInputElement>(null);
506	
507	  async function runQuery(q: string) {
508	    if (!q.trim()) return;
509	    setResult(null);
510	    setPipeline({ step: "sentinel", durations: {} });
511	
512	    const resolved = resolveQuery(q);
513	
514	    // simulate pipeline steps
515	    const stepDurations: Partial<Record<PipelineStep, number>> = {};
516	    for (const step of STEP_ORDER) {
517	      const d = 420 + Math.random() * 340;
518	      stepDurations[step] = d;
519	      await new Promise((res) => setTimeout(res, d));
520	      setPipeline((prev) => ({
521	        step: STEP_ORDER[STEP_ORDER.indexOf(step) + 1] ?? "done",
522	        durations: { ...prev.durations, [step]: d },
523	      }));
524	    }
525	
526	    setResult(resolved);
527	    setHistory((prev) => [{ query: q, result: resolved }, ...prev.slice(0, 4)]);
528	  }
529	
530	  function submit(q: string) {
531	    setQuery(q);
532	    runQuery(q);
533	  }
534	
535	  return (
536	    <div className="flex h-full bg-[#050505] overflow-hidden">
537	      {/* ── Left — history ─────────────────────────────────────── */}
538	      <div className="hidden lg:flex w-[200px] flex-shrink-0 flex-col border-r border-white/[0.05] py-4 overflow-hidden">
539	        <div className="px-3 mb-3 flex-shrink-0">
540	          <div className="flex items-center gap-1.5">
541	            <div className="w-[2px] h-3.5 rounded-full bg-violet-500/70" />
542	            <span className="text-[8px] font-mono text-zinc-600 uppercase tracking-[0.18em]">
543	              History
544	            </span>
545	          </div>
546	        </div>
547	        <div className="flex-1 overflow-y-auto px-2" style={{ scrollbarWidth: "none" }}>
548	          <AnimatePresence>
549	            {history.length === 0 ? (
550	              <p className="text-[9px] font-mono text-zinc-800 px-2">No queries yet</p>
551	            ) : (
552	              history.map((h, _i) => (
553	                <motion.button
554	                  key={`${h.query}-${h.result.type}`}
555	                  initial={{ opacity: 0, y: -4 }}
556	                  animate={{ opacity: 1, y: 0 }}
557	                  transition={{ duration: 0.2 }}
558	                  onClick={() => submit(h.query)}
559	                  className="w-full text-left px-2.5 py-2 rounded-lg hover:bg-white/[0.03] transition-colors duration-150 mb-1"
560	                >
