96	export default function ImportFlow() {
97	  const [step, setStep] = useState<WizardStep>(1);
98	  const [batch, setBatch] = useState<BatchResponse | null>(null);
99	  const [selectedId, setSelectedId] = useState("");
100	  const [draftNotes, setDraftNotes] = useState<Record<string, string>>({});
101	  const [draftDecision, setDraftDecision] = useState<Record<string, TechnicianDecision>>({});
102	  const [draftName, setDraftName] = useState<Record<string, string>>({});
103	  const [draftCategory, setDraftCategory] = useState<Record<string, string>>({});
104	  const [commitResult, setCommitResult] = useState<CommitResponse | null>(null);
105	  const [errorMessage, setErrorMessage] = useState<string | null>(null);
106	  const [loading, setLoading] = useState<"pull" | "match" | "review" | "commit" | "upload" | null>(
107	    null
108	  );
109	
110	  const rows = batch?.items ?? [];
111	  const selectedRow = useMemo(
112	    () => rows.find((row) => row.id === selectedId) ?? rows[0] ?? null,
113	    [rows, selectedId]
114	  );
115	
116	  const step1Complete = Boolean(batch && batch.items.length > 0);
117	  const step2Complete =
118	    rows.length > 0 && rows.every((row) => row.normalizedName && row.candidates.length > 0);
119	  const step3Complete =
120	    rows.length > 0 &&
121	    rows.every((row) => {
122	      const decision = getDecision(row, draftDecision);
123	      return row.documents.length > 0 && decision !== "pending" && decision !== "needs-doc";
124	    });
125	
126	  const activeMeta = stepMeta[step];
127	  const ActiveIcon = activeMeta.icon;
128	
129	  async function pullIngressBatch() {
130	    setLoading("pull");
131	    setErrorMessage(null);
132	
133	    const { data, error } = await client.POST("/api/import-flows/ingress/pull");
134	
135	    if (error || !data) {
136	      setErrorMessage(getErrorMessage(error) || "Failed to pull ingress batch.");
137	      setLoading(null);
138	      return;
139	    }
140	
141	    startTransition(() => {
142	      setBatch(data);
143	      setSelectedId(data.items[0]?.id ?? "");
144	      setDraftNotes({});
145	      setDraftDecision({});
146	      setDraftName({});
147	      setDraftCategory({});
148	      setCommitResult(null);
149	      setLoading(null);
150	    });
151	  }
152	
153	  async function runReasoningLayer() {
154	    if (!batch) return;
155	
156	    setLoading("match");
157	    setErrorMessage(null);
158	
159	    const { data, error } = await client.POST("/api/import-flows/{batchId}/match", {
160	      params: { path: { batchId: batch.id } },
161	    });
162	
163	    if (error || !data) {
164	      setErrorMessage(getErrorMessage(error) || "Failed to run reasoning layer.");
165	      setLoading(null);
166	      return;
167	    }
168	
169	    startTransition(() => {
170	      setBatch(data);
171	      setSelectedId(data.items[0]?.id ?? "");
172	      setLoading(null);
173	    });
174	  }
175	
176	  async function uploadPdf(event: ChangeEvent<HTMLInputElement>) {
177	    const file = event.target.files?.[0];
178	    event.target.value = "";
179	
180	    if (!batch || !selectedRow || !file) return;
181	    if (file.type !== "application/pdf" && !file.name.toLowerCase().endsWith(".pdf")) {
182	      setErrorMessage("Only PDF files can be uploaded.");
183	      return;
184	    }
185	
186	    const formData = new FormData();
187	    formData.append("file", file);
188	
189	    setLoading("upload");
190	    setErrorMessage(null);
191	
192	    const response = await fetch(
193	      `/api/import-flows/${batch.id}/items/${selectedRow.id}/documents`,
194	      {
195	        method: "POST",
196	        body: formData,
197	      }
198	    );
199	
200	    if (!response.ok) {
201	      setErrorMessage("Failed to upload PDF for selected item.");
202	      setLoading(null);
203	      return;
204	    }
205	
206	    const nextBatch = (await response.json()) as BatchResponse;
207	
208	    startTransition(() => {
209	      setBatch(nextBatch);
210	      setSelectedId(selectedRow.id);
211	      setLoading(null);
212	    });
213	  }
214	
215	  async function submitReview() {
216	    if (!batch) return;
217	
218	    const payload: ReviewPayload = {
219	      items: rows.map((row) => {
220	        const decision = getDecision(row, draftDecision);
221	        const reviewDecision: ReviewDecision = decision === "pending" ? "confirmed" : decision;
222	        const technicianNotes = draftNotes[row.id] ?? toText(row.technicianNotes);
223	        const normalizedName = draftName[row.id] ?? toText(row.normalizedName);
224	        const category = draftCategory[row.id] ?? toText(row.category);
225	
226	        return {
227	          itemId: row.id,
228	          technicianDecision: reviewDecision,
229	          technicianNotes: technicianNotes || undefined,
230	          normalizedName: normalizedName || undefined,
231	          category: category || undefined,
232	        };
233	      }),
234	    };
235	
236	    setLoading("review");
237	    setErrorMessage(null);
238	
239	    const { data, error } = await client.POST("/api/import-flows/{batchId}/review", {
240	      params: { path: { batchId: batch.id } },
241	      body: payload,
242	    });
243	
244	    if (error || !data) {
245	      setErrorMessage(getErrorMessage(error) || "Failed to submit technician review.");
246	      setLoading(null);
247	      return;
248	    }
249	
250	    startTransition(() => {
251	      setBatch(data);
252	      setSelectedId(data.items[0]?.id ?? "");
253	      setLoading(null);
254	    });
255	  }
256	
257	  async function commitImport() {
258	    if (!batch) return;
259	
260	    setLoading("commit");
261	    setErrorMessage(null);
262	
263	    const { data, error } = await client.POST("/api/import-flows/{batchId}/commit", {
264	      params: { path: { batchId: batch.id } },
265	    });
266	
267	    if (error || !data) {
268	      setErrorMessage(getErrorMessage(error) || "Failed to commit import batch.");
269	      setLoading(null);
270	      return;
271	    }
272	
273	    startTransition(() => {
274	      setCommitResult(data);
275	      setBatch(data.batch);
276	      setLoading(null);
277	    });
278	  }
279	
280	  return (
281	    <div className="min-h-full bg-[#050505] px-4 py-4 md:px-6 md:py-5">
282	      <div className="mx-auto flex max-w-[1500px] flex-col gap-4">
283	        <section className="rounded-[28px] border border-white/[0.07] bg-[radial-gradient(circle_at_top_left,rgba(59,130,246,0.16),transparent_28%),radial-gradient(circle_at_78%_18%,rgba(16,185,129,0.12),transparent_24%),linear-gradient(180deg,#0d0d0d_0%,#070707_100%)] px-5 py-5 md:px-7 md:py-7">
284	          <div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
285	            <div className="max-w-3xl">
286	              <div className="mb-3 flex items-center gap-2">
287	                <span className="rounded-full border border-emerald-500/20 bg-emerald-500/10 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.18em] text-emerald-400">
288	                  Genesis workflow
289	                </span>
290	                <span className="text-[10px] uppercase tracking-[0.16em] text-zinc-600">
291	                  Facility Alpha
292	                </span>
293	              </div>
294	
295	              <h1 className="text-[28px] font-semibold leading-tight tracking-tight text-white md:text-[34px]">
296	                Run Genesis from ingress pull to catalog publish for the same power, cooling,
297	                compute, and network assets shown in Ops.
298	              </h1>
299	
300	              <p className="mt-3 max-w-2xl text-[13px] leading-6 text-zinc-400 md:text-[14px]">
301	                Genesis stages the latest equipment groups, proposes Atlas matches, routes each item
302	                through technician review, and only publishes after final confirmation.
303	              </p>
304	            </div>
305	
306	            <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:min-w-[520px]">
307	              {([1, 2, 3, 4] as WizardStep[]).map((item) => {
308	                const meta = stepMeta[item];
309	                const Icon = meta.icon;
310	                const active = step === item;
311	                const done = item < step;
312	
313	                return (
314	                  <div
315	                    key={item}
316	                    className={`rounded-[20px] border px-4 py-4 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] ${
