16	const SOURCES = ["CRAH-A-01", "CHILLER-A-03", "UPS-01", "PDU-MAIN", "PUMP-CHW-03", "POD-02"];
17	const TYPES: DataPacket["type"][] = [
18	  "telemetry",
19	  "telemetry",
20	  "telemetry",
21	  "alert",
22	  "heartbeat",
23	  "command",
24	];
25	const TYPE_CONFIG = {
26	  telemetry: {
