53	  },
54	};
55	
56	function generatePacket(): DataPacket {
57	  const type = TYPES[Math.floor(Math.random() * TYPES.length)];
58	  const source = SOURCES[Math.floor(Math.random() * SOURCES.length)];
59	  const payloads: Record<DataPacket["type"], string> = {
60	    telemetry: `{"temp":${(18 + Math.random() * 6).toFixed(1)},"fan":${Math.round(60 + Math.random() * 30)},"ts":${Date.now()}}`,
61	    alert: `{"severity":"${Math.random() > 0.5 ? "warning" : "critical"}","code":"THR_${Math.floor(Math.random() * 999)}"}`,
62	    heartbeat: `{"status":"ok","seq":${Math.floor(Math.random() * 99999)}}`,
63	    command: `{"cmd":"SET_SETPOINT","value":${(18 + Math.random() * 2).toFixed(1)}}`,
64	  };
65	  return {
66	    id: Math.random().toString(36).slice(2, 8),
67	    source,
68	    type,
69	    payload: payloads[type],
70	    size: Math.round(Math.random() * 400 + 64),
71	    latency: Math.round(Math.random() * 40 + 2),
72	    timestamp: Date.now(),
73	  };
74	}
75	
76	export default function IngressViz() {
