169	                    {ts.count}
170	                  </span>
171	                </div>
172	              );
173	            })}
174	          </div>
175	        </div>
176	
177	        {/* Packet stream */}
178	        <div
179	          className="flex-1 overflow-y-auto p-3 space-y-1.5 font-mono"
180	          style={{ scrollbarWidth: "none" }}
181	        >
182	          <AnimatePresence mode="popLayout">
183	            {packets.map((p) => {
