export type AssetStatus = "normal" | "warning" | "critical" | "offline";

export interface Asset {
  id: string;
  name: string;
  type: string;
  status: AssetStatus;
  x: number;
  y: number;
  criticality: "high" | "medium" | "low";
  floor: "Mechanical" | "Hall A" | "Hall B";
  zone: string;
  telemetry: { metric: string; value: number; unit: string; trend: "up" | "down" | "stable" }[];
  dependsOn: string[];
}

export interface Technician {
  id: string;
  name: string;
  avatar: string;
  status: "available" | "on-site" | "transit";
  certifications: string[];
  location: string;
  eta?: string;
}

export interface Incident {
  id: string;
  assetId: string;
  severity: "critical" | "high" | "medium";
  detectedAt: string;
  prediction: string;
  confidence: number;
  ttf: number;
  blastRadius: string[];
  recommendedAction: string;
  status: "open" | "dispatched" | "hitl-pending" | "resolved";
}

export interface Job {
  id: string;
  incidentId: string;
  technicianId: string;
  assetId: string;
  status: "assigned" | "en-route" | "on-site" | "closed";
  priority: "critical" | "high" | "medium";
  title: string;
  description: string;
  steps: { id: string; label: string; completed: boolean }[];
  assignedAt: string;
  eta: string;
  partsRequired: string[];
}

// ────────────────────────────────────────────────────────────────
