23	function LiveClock() {
24	  const [t, setT] = useState(new Date());
25	  useEffect(() => {
26	    const id = setInterval(() => setT(new Date()), 1000);
27	    return () => clearInterval(id);
28	  }, []);
29	  const h = t.getHours().toString().padStart(2, "0"),
30	    m = t.getMinutes().toString().padStart(2, "0"),
31	    s = t.getSeconds().toString().padStart(2, "0");
32	  return (
33	    <span className="font-mono text-[11px] text-zinc-500 tabular-nums tracking-[0.08em]">
34	      {h}:{m}:{s}
35	    </span>
36	  );
37	}
38	
39	function useCountUp(target: number, d = 900) {
40	  const [count, setCount] = useState(0);
41	  useEffect(() => {
42	    const start = performance.now();
43	    let f: number;
44	    const tick = (now: number) => {
45	      const p = Math.min((now - start) / d, 1);
46	      setCount(Math.round((1 - (1 - p) ** 3) * target));
47	      if (p < 1) f = requestAnimationFrame(tick);
48	    };
49	    f = requestAnimationFrame(tick);
50	    return () => cancelAnimationFrame(f);
51	  }, [target, d]);
52	  return count;
53	}
54	
55	const chartData = telemetryHistory.slice(18);
