1	import {
2	  Cpu,
3	  Desktop,
4	  Gear,
5	  Lightning,
6	  Network,
7	  Plugs,
8	  Snowflake,
9	  Warning,
10	  WifiHigh,
11	} from "@phosphor-icons/react";
12	import type { Asset, AssetStatus, Incident } from "../../data/mock";
13	import {
14	  DATACENTER_FLOORS,
15	  type FloorKey,
16	  ZONE_SURFACE_COLORS,
17	  type ZoneConfig,
18	  type ZoneVariant,
19	} from "./commandCenterLayout";
20	
21	// ── Props ───────────────────────────────────────────────────────────────────
22	
23	interface Props {
24	  assets: Asset[];
25	  incident: Incident | undefined;
26	  litNodes: Set<string>;
27	  activeFloor: FloorKey;
28	  onAssetClick: (assetId: string) => void;
29	}
30	
31	// ── Helpers ─────────────────────────────────────────────────────────────────
32	
33	function getDerivedStatus(
34	  asset: Asset,
35	  incident: Incident | undefined,
36	  litNodes: Set<string>
37	): AssetStatus {
38	  if (incident?.assetId === asset.id) return "critical";
39	  if (litNodes.has(asset.id)) return "warning";
40	  return asset.status;
41	}
42	
43	function getStatusTone(status: AssetStatus) {
44	  switch (status) {
45	    case "critical":
46	      return { color: "#ef4444", glow: "rgba(239,68,68,0.28)", ring: "rgba(239,68,68,0.55)" };
47	    case "warning":
48	      return { color: "#f59e0b", glow: "rgba(245,158,11,0.24)", ring: "rgba(245,158,11,0.50)" };
49	    case "offline":
50	      return { color: "#71717a", glow: "rgba(113,113,122,0.18)", ring: "rgba(113,113,122,0.35)" };
51	    default:
52	      return { color: "#22c55e", glow: "rgba(34,197,94,0.14)", ring: "rgba(255,255,255,0.12)" };
53	  }
54	}
55	
56	function getAssetIcon(type: string) {
57	  if (type === "Cooling") return Snowflake;
58	  if (type === "Power") return Lightning;
59	  if (type === "Network") return WifiHigh;
60	  return Desktop;
61	}
62	
63	function getAssetAccent(type: string) {
64	  if (type === "Cooling") return "#38bdf8";
65	  if (type === "Power") return "#f59e0b";
66	  if (type === "Network") return "#a78bfa";
67	  return "#34d399";
68	}
69	
70	function getLinkColor(assetType: string, highlighted: boolean) {
71	  if (highlighted) return "rgba(248,113,113,0.9)";
72	  if (assetType === "Cooling") return "rgba(56,189,248,0.42)";
73	  if (assetType === "Power") return "rgba(245,158,11,0.36)";
74	  if (assetType === "Network") return "rgba(167,139,250,0.36)";
75	  return "rgba(255,255,255,0.14)";
76	}
77	
78	function getZoneIcon(variant: ZoneVariant) {
79	  switch (variant) {
80	    case "electrical":
81	      return Plugs;
82	    case "power":
83	      return Lightning;
84	    case "cooling":
85	      return Snowflake;
86	    case "compute":
87	      return Desktop;
88	    case "network":
89	      return Network;
90	    case "mechanical":
91	      return Gear;
92	    case "a":
93	      return Cpu;
94	    case "b":
95	      return Cpu;
96	  }
97	}
98	
99	// ── AssetNode ────────────────────────────────────────────────────────────────
100	
101	function AssetNode({
102	  asset,
103	  status,
104	  isFocused,
105	  isAffected,
106	  onAssetClick,
107	}: {
108	  asset: Asset;
109	  status: AssetStatus;
110	  isFocused: boolean;
111	  isAffected: boolean;
112	  onAssetClick: (id: string) => void;
113	}) {
114	  const statusTone = getStatusTone(status);
115	  const isAlert = isFocused || isAffected || status !== "normal";
116	  const nodeSize = isAlert && asset.criticality === "high" ? 32 : 28;
117	  const accent = getAssetAccent(asset.type);
118	  const Icon = getAssetIcon(asset.type);
119	  const iconSize = nodeSize === 32 ? 16 : 14;
120	
121	  return (
122	    <button
123	      type="button"
124	      className="group absolute -translate-x-1/2 -translate-y-1/2 flex flex-col items-center gap-[3px] z-10"
125	      style={{ left: `${asset.x}%`, top: `${asset.y}%` }}
126	      onClick={(e) => {
127	        e.stopPropagation();
128	        onAssetClick(asset.id);
129	      }}
130	      title={`${asset.name} — ${status}`}
131	      aria-label={`Inspect ${asset.name}`}
132	    >
133	      {/* Ambient glow halo */}
134	      {isAlert && (
135	        <span
136	          className="absolute inset-[-16px] rounded-full animate-pulse pointer-events-none"
137	          style={{
138	            background: `radial-gradient(circle, ${statusTone.glow} 0%, transparent 65%)`,
139	          }}
140	        />
141	      )}
142	
143	      {/* Node circle */}
144	      <span
145	        className="relative flex items-center justify-center rounded-full transition-all duration-200 group-hover:scale-110"
146	        style={{
