150	          backgroundColor: `color-mix(in srgb, ${accent} 9%, #090c11)`,
151	          border: `1.5px solid ${isAlert ? statusTone.ring : "rgba(255,255,255,0.11)"}`,
152	          boxShadow: isAlert
