241	  floorAssetIds,
242	  onAssetClick,
243	}: {
244	  assetsByZone: { zoneName: string; zoneCfg: ZoneConfig; assets: Asset[] }[];
245	  incident: Incident | undefined;
246	  litNodes: Set<string>;
