377	              >
378	                {/* SVG dependency edges */}
379	                <svg
380	                  aria-hidden="true"
381	                  className="pointer-events-none absolute inset-0 h-full w-full"
382	                >
383	                  {links.map((link) => (
384	                    <g key={link.id}>
385	                      {/* Shadow stroke for depth */}
