387	                        x1={`${link.from.x}%`}
388	                        y1={`${link.from.y}%`}
389	                        x2={`${link.to.x}%`}
390	                        y2={`${link.to.y}%`}
391	                        stroke={link.highlighted ? "rgba(239,68,68,0.14)" : "rgba(0,0,0,0.50)"}
392	                        strokeWidth={link.highlighted ? 6 : 3.5}
393	                        strokeLinecap="round"
