401	                        stroke={getLinkColor(link.from.type, link.highlighted)}
402	                        strokeWidth={link.highlighted ? 2.0 : 1.2}
403	                        strokeDasharray={link.highlighted ? "5 4" : "2 6"}
404	                        strokeLinecap="round"
405	                        className={link.highlighted ? "dash-flow" : ""}
406	                      />
407	                    </g>
408	                  ))}
409	                </svg>
410	
411	                {/* Asset nodes */}
412	                {zoneAssets.map((asset) => {
413	                  const status = getDerivedStatus(asset, incident, litNodes);
